sys_script_include.script:
var EsrSubcategoryAjax = Class.create()

EsrSubcategoryAjax.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    /**
     * Reports how many active subcategories exist for a category, so the form
     * can tell the user when a category has none configured yet.
     *
     * Client parameter: sysparm_category
     * Returns JSON: { category, label, count }
     */
    getCategoryInfo: function () {
        var category = this.getParameter('sysparm_category')
        var utils = new x_412993_employe_1.EsrSubcategoryUtils()

        return JSON.stringify({
            category: category ? '' + category : '',
            label: utils.getCategoryLabel(category),
            count: utils.countForCategory(category),
        })
    },

    /**
     * Confirms a category/subcategory pairing before the form is submitted.
     * This is a convenience for fast feedback only - the authoritative check
     * is the "ESR - Validate category and subcategory" business rule.
     *
     * Client parameters: sysparm_category, sysparm_subcategory
     * Returns JSON: { valid, reason, message }
     */
    validatePair: function () {
        var category = this.getParameter('sysparm_category')
        var subcategory = this.getParameter('sysparm_subcategory')
        var utils = new x_412993_employe_1.EsrSubcategoryUtils()

        return JSON.stringify(utils.validatePair(category, subcategory))
    },

    type: 'EsrSubcategoryAjax',
})
